from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
inventory=json.loads((R/'reports/1.1/glossary-current-inventory.json').read_text(encoding='utf-8'))
by={x['term']:x for x in inventory}
groups=[]
def add(priority,terms,issue,action):
 groups.append(dict(id=f'G{len(groups)+1:02}',priority=priority,terms=terms.split('|'),issue=issue,recommendation=action))
add('Placement / consolidation','hertz','Defined in 11.2 through the Hertz/EM-wave discussion and restricted to EM waves, though 5.2 already explicitly introduces the unit.','Make 5.2 the formal introduction; define Hz as inverse seconds for frequency of any periodic process. Link from 11.2.')
add('Placement / consolidation','standing wave','Glossary is in 11.3, attached to the antenna application; 5.6 already explains standing waves in detail.','Move the formal glossary association to 5.6; fixed nodes describe the pattern, not absence of motion everywhere.')
add('Placement / consolidation','resonant|resonate|resonance','Three forms of the same concept, including a later incidental adjective in 11.3; current resonance definition names driving frequency but omits the enhanced response.','Use resonance as the canonical entry in 5.4; make verb/adjective forms aliases or links. Explain enhanced response near a natural frequency.')
add('Placement / consolidation','vector addition','Glossary appears in 9.5 without a corresponding explicit vector-addition paragraph there; wording unnecessarily includes positions.','Introduce explicitly with vectors in 1.3 if vector addition is to be taught there; otherwise attach to the first actual worked addition. Do not merely move the glossary without adding instruction.')
add('Placement / consolidation','electric field strength|magnetic field strength','General quantities are glossary terms in the 11.3 EM-wave application.','Associate electric-field magnitude with 9.4 and magnetic-field magnitude with 10.5; distinguish the introductory B usage from the technical H meaning of magnetic field strength.')
add('Placement / consolidation','thermal agitation','Defined through microwave heating in 11.5 rather than the earlier thermal-physics treatment.','Use thermal motion as the canonical term in Chapter 8, with an explicit microscopic explanation near temperature/ideal-gas discussion; retain thermal agitation as an alias.')
add('Placement / consolidation','double-slit interference','Glossary entry in 12.7 has no corresponding explanatory paragraph there; the local source reads as an inherited leftover.','Review whether the concept is actually taught in the current sequence. Either add a deliberate introduction in the wave/quantum-wave discussion or remove this orphan entry; do not choose a location solely from an incidental mention.')
add('Placement / consolidation','decay equation','In 14.5 the prose means a nuclear transformation equation, but the glossary means the time-dependent radioactive decay law.','Split the senses: nuclear decay equation in 14.5 and radioactive decay law in 14.6, or rename the glossary entry and define each at its actual use.')
add('Placement / consolidation','photon','Formal entry is in 12.3 although the newly canonical gamma-ray definition in 11.4 already uses photon, and earlier radiation passages do too.','Decide whether to give a brief first definition in 11.4 with deeper treatment in 12.3, or deliberately mark the earlier use as a preview. Keep one canonical glossary entry.')
add('Placement / consolidation','current|electric current|voltage|potential difference (or voltage)','Exact-string deduplication missed these synonymous entries. The later voltage definition also slips from a difference to potential.','Keep electric current in 9.8 and potential difference (voltage) in 9.6; make later forms links or explicit aliases, not independent definitions.')
add('Placement / consolidation','proton|protons','Singular/plural entries describe the same particle in 9.2 and 14.4.','Use one proton entry; early charge description can precede later nuclear/quark detail, with a cross-reference.')
add('Placement / consolidation','second law of motion|Newton’s second law of motion','Same law appears as separate glossary entries in 2.4 and 4.2.','Retain Newton’s second law in 2.4 and link the momentum formulation in 4.2; qualify average versus instantaneous force.')
add('Placement / consolidation','activity|rate of decay','Two entries describe the same quantity in 14.6.','Use activity (decay rate) as one definition, distinguishing expected activity from a finite observed count rate.')
add('Placement / consolidation','magnitude of static friction|magnitude of kinetic friction|magnetic field strength (magnitude) produced by a long straight current-carrying wire|magnetic field strength at the center of a circular loop|magnetic field strength inside a solenoid|radius of a nucleus|energies of hydrogen-like atoms|hydrogen spectrum wavelengths','Several glossary headwords are equation labels or descriptions of calculations.','Consider moving these to equation summaries and leaving the conceptual headwords in the glossary. Preserve anchors and all exercise numbers.')
add('Placement / consolidation','electron capture equation|change in angular velocity|change in momentum','Circular or procedural entries contribute little beyond the corresponding concept/formula.','Review whether these deserve glossary entries; use explanatory equations or cross-references if not.')
add('Correctness / concept','normal force','Defined as supporting weight on a resting surface; excludes walls, moving contacts, and other normal forces.','Define the perpendicular component of a contact force at a surface; revise the introducing prose in 2.6 if it has the same restriction.')
add('Correctness / concept','lever arm','Uses distance to the point of application instead of distance to the line of action.','Correct in 6.3 to perpendicular distance from the axis/pivot to the force’s line of action; check accompanying diagram/prose.')
add('Correctness / concept','voltage drop|Joule’s law','Voltage drop is called loss of electrical power; Joule’s law is presented as P=IV.','In 9.11 define potential decrease and distinguish general electrical power P=IV from resistive heating P=I²R. Review the explicit Joule’s-law sentence in the source too.')
add('Correctness / concept','electromagnetism|electromagnetic force','Electromagnetism is defined as using current to make magnets, and the prose repeats that definition.','Define the broader electric/magnetic interaction framework in 9.1 or a deliberate introductory passage; reserve current-produced magnetism for the electromagnet example in 10.3.')
add('Correctness / concept','Ampere’s law|Biot-Savart law','Ampere’s-law entry describes summing field contributions, closer to Biot-Savart; Biot-Savart definition says only that a specific equation exists.','Give distinct qualitative statements in 10.8, with the magnetostatic scope of Ampere’s law and later Maxwell extension made clear.')
add('Correctness / concept','Faraday cage|electrostatic equilibrium','Cage is said to prevent charge penetrating its surface; equilibrium says all free charges stop moving.','Use electrostatic field shielding and absence of net macroscopic charge flow; microscopic motion continues. Keep in 9.7.')
add('Correctness / concept','absolute zero|temperature','Absolute zero says all molecular motion ceases; temperature is circularly defined by thermometer reading.','Define temperature through thermal equilibrium/heat-flow direction at this level and avoid denying quantum zero-point motion. Keep in 8.2.')
add('Correctness / concept','superposition|overtones|constructive interference|destructive interference','Superposition only says waves arrive together; overtones are equated with integer multiples; interference definitions cover only limiting phase cases.','State addition of disturbances, distinguish overtones from harmonics, and distinguish partial from complete interference in 5.6.')
add('Correctness / concept','SI units|fundamental units|metric system','SI examples include litre without distinguishing its accepted non-SI status; base units are defined by measurement procedures rather than their role in the system.','Update the unit-system explanation and definitions together in 0.3, using SI base/derived terminology and examples.')
add('Correctness / concept','atomic mass|nuclear reaction energy','Atomic mass is given as the sum of constituent masses, omitting binding; reaction energy is called created.','In 14.4 define the atom’s mass including binding effects; in 14.5 define energy released/absorbed from initial-final mass-energy difference.')
add('Correctness / concept','hadrons|leptons','Glossary still uses feel/do not feel the strong force, despite revised prose explaining composite hadrons and elementary leptons.','Synchronize with the approved 14.13 prose. The old definitions wrongly include quarks/gluons as hadrons and photons as leptons.')
add('Correctness / concept','electron family number|muon family number|tau family number|conservation of total electron family number|conservation of total muon family number','Definitions assign ±1 without identifying particle versus antiparticle and state unqualified family-number conservation.','Explain counting particles minus antiparticles; qualify family conservation in light of neutrino oscillations, consistent with the existing discussion. Introduce in 14.13 and align earlier beta-decay references.')
add('Correctness / concept','gauge boson|Feynman diagram','Gauge boson includes all four forces without qualification; Feynman diagram is treated as a literal time-position graph limited to virtual-particle exchange.','Define the Standard Model gauge carriers and diagrams as representations of interaction contributions. Keep explicit caution that a diagram is not a literal trajectory plot. Review 14.12/14.13 prose together.')
add('Correctness / concept','quantum chromodynamics|electroweak theory|grand unified theory|superstring theory','QCD is nearly circular; electroweak definition is vague; GUT and string entries sound established rather than proposed.','Define scope clearly in 14.14: QCD describes strong interactions of quarks/gluons; distinguish established electroweak theory from proposed further unification and string frameworks.')
add('Correctness / concept','positron|electron neutrino|neutrino|antielectron','Positron is defined by one production channel; electron-neutrino definition does not distinguish it from other neutral elementary particles.','Define identity and flavor in 14.5, then describe production examples. Retain antielectron only as an explicit alias.')
add('Correctness / concept','beta ray|radioactivity|decay|gamma decay','Beta entry excludes positrons; radioactivity/decay emphasize emitted rays or particles too narrowly for electron capture; gamma decay says gamma particle.','Review the nuclear-decay family together in 14.2/14.5, including spontaneous transformation and photon emission.')
add('Correctness / concept','scintillators|Geiger tube|radiation detector','Scintillators are called a method rather than materials; Geiger tube is identified by an audio output supplied by readout electronics.','Define the detector mechanisms in 14.3; separate scintillating material, tube, and associated electronics.')
add('Correctness / concept','breeder reactors|breeding|criticality|supercriticality|critical mass','Breeding is restricted to plutonium production; criticality uses easily; supercriticality describes an outcome rather than neutron multiplication balance.','Define fissile-material production more generally and criticality through neutron balance in 14.10. Note that critical mass depends on geometry, composition, moderation and surroundings.')
add('Correctness / concept','Heisenberg’s uncertainty principle|uncertainty in momentum|uncertainty in position|probability wave','Wording can imply instrument error or ignorance; probability wave is too vague.','Clarify intrinsic quantum spreads versus measurement imperfections in 12.5; treat energy-time carefully rather than as an identical operator pair. Requires coordinated prose review.')
add('Correctness / concept','time dilation|proper time|relativistic Doppler effects','Time dilation suggests a moving observer’s own time slows; proper time refers to one event rather than an interval; Doppler wording says radiation moves relative to observer.','Clarify comparison of clocks/event pairs and source-observer motion in 13.3/13.5; retain existing equations after checking assumptions.')
add('Wording / scope','mass|inertia|energy|time','Broad introductory definitions are familiar but under-specified or circular: quantity of matter, remain in motion, ability to do work, and change.','Review as a foundational-language batch. Prefer operational relationships without imposing advanced formalism; current introduction sections are generally appropriate.')
add('Wording / scope','distance|range|trajectory|motion|centripetal acceleration|centripetal force','Distance duplicates displacement magnitude; range says maximum; some definitions silently assume ideal projectiles or uniform circles.','State distance-between-points versus path length, actual projectile horizontal range, and radial acceleration/force scope. Keep in Chapter 1/2 introductions.')
add('Wording / scope','deformation|restoring force|spring constant|static friction','Deformation is just displacement; restoring force is described as opposing another force; static friction opposes motion despite no slipping.','Describe change of shape/size, return toward equilibrium, stiffness, and opposition to impending relative slipping in 2.7/2.8.')
add('Wording / scope','electrical energy|chemical energy|thermal energy|internal energy','Definitions can imply electrical energy requires current, bond breaking releases energy by itself, or thermal energy is only kinetic.','Coordinate energy-form definitions in 3.5 with the microscopic treatment in Chapter 8. Preserve the distinction between energy stored and energy transferred.')
add('Wording / scope','pressure|buoyant force|Bernoulli’s equation|Bernoulli’s principle','Pressure wording is awkward; buoyancy scope is not stated; Bernoulli relation is said to hold through the fluid without streamline/flow qualifications.','Clarify normal force per area, hydrostatic context and the steady ideal-flow assumptions in Chapter 7.')
add('Wording / scope','heat of sublimation|latent heat coefficient|specific heat|isobaric process|reversible process','Mass normalization and conditions are unclear; isobaric wrongly requires work; reversible definition is confined to heat engines.','Clarify specific quantities and process conditions at their present Chapter 8 introductions.')
add('Wording / scope','entropy','Disorder is offered as the principal conceptual association and energy available for work is underspecified.','Review 8.13 and 8.14 together; use thermodynamic definition first and statistical interpretation later. This is an editorial choice requiring more than a glossary-only swap.')
add('Wording / scope','field|point charge|test charge|electric charge|law of conservation of charge|electron','Field is restricted to a force map; point/test charge definitions rely on arbitrary symbol names; charge conservation is reduced to pair creation; electron implies a classical orbit.','Improve in place in 9.2/9.4, with a small/nonperturbing test charge and charge conservation for isolated systems; avoid literal electron orbits.')
add('Wording / scope','Curie temperature|permeability of free space|Lenz’s law|AC voltage|AC current','Curie entry implies no induced magnetization above the transition; μ0 is presented as exact; Lenz wording assigns opposition to voltage; AC is equated with sinusoidal behavior.','Clarify loss of spontaneous ferromagnetism, approximate numerical μ0, induced-current field direction, and sinusoidal AC as the case studied.')
add('Wording / scope','dispersion|focal point|focal length|converging lens|diverging lens|converging mirror|real image|virtual image','Definitions lean on one demonstration or geometry; image definitions omit ray convergence/backward extension.','In Chapter 11 distinguish frequency-dependent refractive behavior, paraxial focal geometry and actual/apparent ray origins. Qualify lens shape by surrounding refractive index.')
add('Wording / scope','polarization|direction of polarization|horizontally polarized|vertically polarized|unpolarized|birefringent','Adjacent definitions still assume linear polarization although the new polarized-light entry allows more general polarization.','Review 11.11 as a coherent group; explicitly limit directional-plane language to linearly polarized light.')
add('Wording / scope','blackbody radiation|Planck law|planetary model of the atom|Bohr radius|hydrogen spectrum wavelengths|work function|correspondence principle','Some are historical descriptions instead of definitions; planetary model says only most familiar; Bohr radius says mean orbit radius; hydrogen wavelengths are restricted to visible light.','Clarify at current introductions, with model scope and minimum electron-removal energy. Keep distinctions between quantum states and literal classical orbits.')
add('Wording / scope','decay constant|curie|radiopharmaceutical|fission fragments|liquid drop model|nucleons|neutron','Several are vague, grammatical, or use an example as the definition. Curie is historically tied to radium rather than first stating the defined conversion.','Define quantities/objects directly in Chapter 14; decay constant as decay probability rate, radiopharmaceutical as radioactive diagnostic/therapeutic preparation, fission fragments as resulting nuclei. Check local prose alongside each.')
add('Wording / scope','break-even|ignition|inertial confinement|proton-proton cycle','Fusion gain has multiple boundaries; ignition lacks self-heating explanation; confinement is limited to lasers; cycle is only a list of reactions without multiplicities/net result.','Review together in 14.9, stating the intended gain measure and physical mechanism. Preserve equations but add conceptual definition where needed.')
add('Wording / scope','baryon number|conservation of total baryon number','Definitions lean on historical nucleon counting and unqualified conservation.','Keep historical operational introduction, then add quark-count interpretation after quarks; match the agreed staged treatment of mesons/baryons.')
add('Optional pruning','statistical analysis|TV|human metabolism|laser printer|ink-jet printer|simple circuit|magnetized','Some entries are general vocabulary, detailed applications, or a restricted example presented as a general term.','Maintainer decision: retain only if useful to learning objectives; otherwise explain locally without creating a formal glossary headword. No automatic deletions recommended.')
groups[3]['status']='Resolved: glossary entry removed; no additional vector-addition instruction. Pending preview refresh.'
groups[5]['status']='Resolved: redundant glossary and formal-term styling removed; thermal motion already explained in earlier energy and heat sections. Pending preview refresh.'
groups[6]['status']='Resolved: glossary entry removed. Pending preview refresh.'
groups[7]['status']='Resolved: decay equation glossary entry removed; ordinary discussion retained. Pending preview refresh.'
groups[8]['status']='Resolved: retain formal photon definition in Section 12.3; Section 11.4 is an incidental mention. Existing source already follows this arrangement; no textbook edit needed.'
for i in (13,14): groups[i]['status']='Resolved: glossary entries and formal-term styling removed; equations and explanations retained. Pending preview refresh.'
groups[18]['status']='Resolved: electromagnet definition and glossary in 10.3; electromagnetism definition and glossary in 11.2. Pending preview refresh.'

for i in [1,2,3,10,11,12,13,16,18,21,23,24,25,26,30,31,32,35,37,38,40,41,43,44,45,48,50]: groups[i-1]['status']='Applied: focused glossary and prose corrections; pending preview refresh.'
for i in [17,33]: groups[i-1]['status']='Held for maintainer review: broader prose change; exact proposal in glossary-wording-decisions.md.'
groups[19]['status']='Applied: approved prose and glossary definitions, with stable linked Maxwell section title. Pending preview refresh.'
groups[21]['status']='Applied: approved temperature definition and simple absolute-zero wording, without quantum caveat. Pending preview refresh.'
groups[27]['status']='Applied: approved Feynman-diagram and gauge-boson wording, including gauge field. Pending preview refresh.'
for i in [5,17,27,29,33,34,36,39,42,46,47,49,51]: groups[i-1]['status']='Applied: maintainer-approved simplified wording and coordinated prose; G49 definitions only; pending preview refresh.'
out={'scope':'All 523 source glossary definitions reviewed; rendered 524th dfn is nested alias moment of inertia, not an independent definition.','status':'Original audit snapshot with current group decisions; see individual statuses and glossary-wording-decisions.md','groups':groups}
(R/'reports/1.1/glossary-quality-review.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# Glossary quality and introduction-point review','',out['scope'],'','Original audit snapshot; decisions and applied corrections are recorded under each group. See glossary-wording-decisions.md for exact proposals still awaiting review. Applied changes are pending preview refresh. This is an editorial triage, not a complete external fact-check of every definition. Mathematics in the inventory is flattened text; no formatting defects are inferred from that flattening.','',f'{len(groups)} review groups. Terms not listed were not flagged in this pass; that is not certification of every surrounding passage.','','Priority order: placement/consolidation; substantive correctness; wording/scope; optional pruning.','', 'The earlier report of 524 standalone entries counted a nested term, moment of inertia, inside the rotational inertia definition. There are 523 standalone definitions and no exact-name duplicates. Semantic aliases still need review.','']
for g in groups:
 lines.extend([f"## {g['id']} — {', '.join(g['terms'])}",'',f"**{g['priority']}**",'',g['issue'],'', '**Recommended review:** '+g['recommendation'],'','Current entries:',''])
 if g.get('status'): lines.extend(['**Decision:** '+g['status'],''])
 for t in g['terms']:
  x=by[t];lines.append(f"- **{t}** — {x['section']}, {x['title']}: {x['definition']}")
 lines.append('')
lines.extend(['## Source checks','', '- [BIPM SI base units](https://www.bipm.org/en/measurement-units/si-base-units) and [SI Brochure](https://www.bipm.org/documents/d/guest/si-brochure-9-2_01): base/derived units and litre status.','- [OpenStax torque](https://openstax.org/books/university-physics-volume-1/pages/10-6-torque): lever arm is distance to the force line of action.','- [CERN QCD overview](https://home.cern/science/physics/heavy-ions-and-quark-gluon-plasma/): quark/gluon content and scope of QCD.','', 'Placement evidence was checked against maintained source paragraphs for hertz (5.2/11.2), standing waves (5.6/11.3), resonant (11.3), vector addition (9.5), double-slit interference (12.7), thermal agitation (11.5), decay equation (14.5), photon (12.3), electromagnetism (10.3), Joule’s law (9.11), positron/electron neutrino (14.5), and gauge boson (14.13). Proposed new introduction points that lack existing explanatory prose are explicitly identified as proposals.'])
(R/'reports/1.1/glossary-quality-review.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'review_groups':len(groups),'flagged_terms':len(set(t for g in groups for t in g['terms'])),'report':'reports/1.1/glossary-quality-review.md'}))
if __name__=='__main__':pass
